def blend_cards(start):
    cells = []
    for i in range(start, min(start + 6, len(BLENDS))):
        name, tag, rows, how = BLENDS[i]
        cells.append(M(i + 1, name, tag, rows, how, meta=('250 ml · sem cafeína', '250 ml · caffeine-free') if i not in (10, 16) else ('1 caneca · com leite', '1 mug · with milk')))
    return grid(2, *cells)


def diary(lang):
    days = ['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom'] if lang == 'pt' else ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
    cols = [('Último café / chá com cafeína', 'Last coffee / caffeinated tea'), ('Blend da noite', 'Evening blend'), ('Hora de deitar', 'Bedtime'), ('Telas desligadas', 'Screens off'), ('Como acordei (1 a 5)', 'How I woke (1 to 5)')]
    head = '<tr><th></th>' + ''.join(f'<th>{esc(tr(L(*c), lang))}</th>' for c in cols) + '</tr>'
    rows = ''.join(f'<tr><td>{d}</td>' + '<td style="height:11mm"></td>' * len(cols) + '</tr>' for d in days)
    return f'<table class="data">{head}{rows}</table>'


